  ('念奴娇 · 赤壁怀古', '苏教', '高中'),
  ('六国论', '苏教', '高中'),
  ('醉花阴', '苏教', '高中')
) AS g(title, edition, level)
JOIN poems p ON p.title = g.title
ON CONFLICT DO NOTHING;
